//! Byte-equality tests against golden files generated by CPython 3.12 with
//! the pinned Django/DRF/kombu versions.
//!
//! The corpus and its provenance are described in
//! `apps/server/tools/golden/serde_corpus.py`. Each line is one case; see that
//! file for the record schema and the Python call behind every category.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};

use chrono::{DateTime, NaiveDate, NaiveDateTime, NaiveTime, TimeDelta};
use plane_serde::values::{
    DjangoDateTime, DjangoNaiveDateTime, DjangoTime, DjangoTimedelta, DrfDateTime, DrfDecimal,
    DrfNaiveDateTime, EncoderDecimal, KombuBytes, KombuDate, KombuDateTime, KombuDecimal,
    KombuNaiveDateTime, KombuTime, KombuUuid, PyDate, PyTime, PyTimedelta,
};
use plane_serde::{Dialect, Error, PyDecimal, to_vec, transcode_json};
use serde::Serialize;
use serde::ser::{SerializeMap, SerializeSeq, Serializer};
use uuid::Uuid;

// ---------------------------------------------------------------------------
// Golden record
// ---------------------------------------------------------------------------

#[derive(Debug, serde::Deserialize)]
struct Record {
    cat: String,
    dialects: Vec<String>,
    #[serde(rename = "in")]
    input: String,
    #[serde(default)]
    out: Option<String>,
    #[serde(default)]
    error: Option<bool>,
    #[serde(default)]
    max_digits: Option<u32>,
    #[serde(default)]
    decimal_places: Option<u32>,
}

impl Record {
    fn dialect(name: &str) -> Dialect {
        match name {
            "drf" => Dialect::Drf,
            "django" => Dialect::Django,
            "kombu" => Dialect::Kombu,
            other => panic!("unknown dialect {other}"),
        }
    }
}

// ---------------------------------------------------------------------------
// Typed value for nested structures
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
enum TestValue {
    Null,
    Bool(bool),
    Int(i64),
    UInt(u64),
    Float(f64),
    Str(String),
    List(Vec<TestValue>),
    Map(Vec<(TestValue, TestValue)>),
}

impl TestValue {
    fn from_json(value: &serde_json::Value) -> Self {
        let object = value
            .as_object()
            .unwrap_or_else(|| panic!("description node is not an object: {value}"));
        let tag = object
            .get("t")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_else(|| panic!("description node has no tag: {value}"));
        match tag {
            "null" => TestValue::Null,
            "bool" => TestValue::Bool(
                object
                    .get("v")
                    .and_then(serde_json::Value::as_bool)
                    .unwrap_or_else(|| panic!("bool node has no value: {value}")),
            ),
            "int" => {
                let text = object
                    .get("v")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_else(|| panic!("int node has no value: {value}"));
                match text.parse::<i64>() {
                    Ok(value) => TestValue::Int(value),
                    Err(_) => TestValue::UInt(
                        text.parse::<u64>()
                            .unwrap_or_else(|_| panic!("int out of range: {text}")),
                    ),
                }
            }
            "float" => {
                let text = object
                    .get("v")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_else(|| panic!("float node has no value: {value}"));
                TestValue::Float(
                    text.parse::<f64>()
                        .unwrap_or_else(|_| panic!("bad float text: {text}")),
                )
            }
            "str" => TestValue::Str(
                object
                    .get("v")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_else(|| panic!("str node has no value: {value}"))
                    .to_owned(),
            ),
            "arr" => TestValue::List(
                object
                    .get("v")
                    .and_then(serde_json::Value::as_array)
                    .unwrap_or_else(|| panic!("arr node has no value: {value}"))
                    .iter()
                    .map(TestValue::from_json)
                    .collect(),
            ),
            "obj" => TestValue::Map(
                object
                    .get("v")
                    .and_then(serde_json::Value::as_array)
                    .unwrap_or_else(|| panic!("obj node has no value: {value}"))
                    .iter()
                    .map(|entry| {
                        let pair = entry
                            .as_array()
                            .unwrap_or_else(|| panic!("object entry is not a pair: {entry}"));
                        assert_eq!(pair.len(), 2, "object entry is not a pair: {entry}");
                        (
                            TestValue::from_json(&pair[0]),
                            TestValue::from_json(&pair[1]),
                        )
                    })
                    .collect(),
            ),
            other => panic!("unknown description tag {other}"),
        }
    }

    fn map_key(&self) -> MapKeyValue<'_> {
        match self {
            TestValue::Str(value) => MapKeyValue::Str(value),
            TestValue::Bool(value) => MapKeyValue::Bool(*value),
            TestValue::Int(value) => MapKeyValue::Int(*value),
            TestValue::UInt(value) => MapKeyValue::UInt(*value),
            TestValue::Float(value) => MapKeyValue::Float(*value),
            TestValue::Null => MapKeyValue::Null,
            other => panic!("non-scalar map key: {other:?}"),
        }
    }
}

impl Serialize for TestValue {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        match self {
            TestValue::Null => serializer.serialize_unit(),
            TestValue::Bool(value) => serializer.serialize_bool(*value),
            TestValue::Int(value) => serializer.serialize_i64(*value),
            TestValue::UInt(value) => serializer.serialize_u64(*value),
            TestValue::Float(value) => serializer.serialize_f64(*value),
            TestValue::Str(value) => serializer.serialize_str(value),
            TestValue::List(values) => {
                let mut sequence = serializer.serialize_seq(Some(values.len()))?;
                for value in values {
                    sequence.serialize_element(value)?;
                }
                sequence.end()
            }
            TestValue::Map(entries) => {
                let mut map = serializer.serialize_map(Some(entries.len()))?;
                for (key, value) in entries {
                    map.serialize_key(&key.map_key())?;
                    map.serialize_value(value)?;
                }
                map.end()
            }
        }
    }
}

enum MapKeyValue<'a> {
    Str(&'a str),
    Bool(bool),
    Int(i64),
    UInt(u64),
    Float(f64),
    Null,
}

impl Serialize for MapKeyValue<'_> {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        match self {
            MapKeyValue::Str(value) => serializer.serialize_str(value),
            MapKeyValue::Bool(value) => serializer.serialize_bool(*value),
            MapKeyValue::Int(value) => serializer.serialize_i64(*value),
            MapKeyValue::UInt(value) => serializer.serialize_u64(*value),
            MapKeyValue::Float(value) => serializer.serialize_f64(*value),
            // Python's json module turns a None key into the string "null".
            MapKeyValue::Null => serializer.serialize_str("null"),
        }
    }
}

enum IntValue {
    Signed(i64),
    Unsigned(u64),
}

impl Serialize for IntValue {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        match self {
            IntValue::Signed(value) => serializer.serialize_i64(*value),
            IntValue::Unsigned(value) => serializer.serialize_u64(*value),
        }
    }
}

// ---------------------------------------------------------------------------
// Category dispatch
// ---------------------------------------------------------------------------

fn render(record: &Record, dialect: Dialect) -> Result<Vec<u8>, Error> {
    let input = decode_base64(&record.input);
    match record.cat.as_str() {
        "float" => {
            let bits: [u8; 8] = input.as_slice().try_into().expect("8 float bytes");
            to_vec(dialect, &f64::from_le_bytes(bits))
        }
        "float32" => {
            let bits: [u8; 4] = input.as_slice().try_into().expect("4 float bytes");
            to_vec(dialect, &f64::from(f32::from_le_bytes(bits)))
        }
        "f64_nonfinite" => {
            let bits: [u8; 8] = input.as_slice().try_into().expect("8 float bytes");
            to_vec(dialect, &f64::from_le_bytes(bits))
        }
        "int" => {
            let text = as_str(&input);
            let value = match text.parse::<i64>() {
                Ok(value) => IntValue::Signed(value),
                Err(_) => IntValue::Unsigned(text.parse::<u64>().expect("u64 literal")),
            };
            to_vec(dialect, &value)
        }
        "none" => to_vec::<Option<u8>>(dialect, &None),
        "string" => to_vec(dialect, &as_str(&input)),
        "structure" | "mapkeys" => {
            let description: serde_json::Value =
                serde_json::from_slice(&input).expect("description JSON");
            to_vec(dialect, &TestValue::from_json(&description))
        }
        "drf_datetime" => to_vec(dialect, &DrfDateTime(parse_aware(&input))),
        "django_datetime" => to_vec(dialect, &DjangoDateTime(parse_aware(&input))),
        "kombu_datetime" => to_vec(dialect, &KombuDateTime(parse_aware(&input))),
        "drf_naive_datetime" => to_vec(dialect, &DrfNaiveDateTime(parse_naive(&input))),
        "django_naive_datetime" => to_vec(dialect, &DjangoNaiveDateTime(parse_naive(&input))),
        "kombu_naive_datetime" => to_vec(dialect, &KombuNaiveDateTime(parse_naive(&input))),
        "py_date" => to_vec(dialect, &PyDate(parse_date(&input))),
        "py_time" => to_vec(dialect, &PyTime(parse_time(&input))),
        "django_time" => to_vec(dialect, &DjangoTime(parse_time(&input))),
        "kombu_time" => to_vec(dialect, &KombuTime(parse_time(&input))),
        "kombu_date" => to_vec(dialect, &KombuDate(parse_date(&input))),
        "py_timedelta" => to_vec(dialect, &PyTimedelta(parse_timedelta(&input))),
        "django_timedelta" => to_vec(dialect, &DjangoTimedelta(parse_timedelta(&input))),
        "drf_decimal" => {
            let value = PyDecimal::parse(as_str(&input)).expect("decimal");
            let max_digits = record.max_digits.expect("max_digits");
            let decimal_places = record.decimal_places.expect("decimal_places");
            to_vec(dialect, &DrfDecimal::new(value, max_digits, decimal_places))
        }
        "encoder_decimal_drf" => to_vec(
            dialect,
            &EncoderDecimal::Drf(PyDecimal::parse(as_str(&input)).expect("decimal")),
        ),
        "encoder_decimal_django" => to_vec(
            dialect,
            &EncoderDecimal::Django(PyDecimal::parse(as_str(&input)).expect("decimal")),
        ),
        "kombu_decimal" => to_vec(
            dialect,
            &KombuDecimal(PyDecimal::parse(as_str(&input)).expect("decimal")),
        ),
        "uuid" => to_vec(dialect, &Uuid::parse_str(as_str(&input)).expect("uuid")),
        "kombu_uuid" => to_vec(
            dialect,
            &KombuUuid(Uuid::parse_str(as_str(&input)).expect("uuid")),
        ),
        "kombu_bytes" => to_vec(dialect, &KombuBytes(input)),
        "transcode" => {
            let mut out = Vec::new();
            transcode_json(dialect, as_str(&input), &mut out)?;
            Ok(out)
        }
        other => panic!("unknown golden category {other}"),
    }
}

fn parse_aware(input: &[u8]) -> DateTime<chrono::FixedOffset> {
    DateTime::parse_from_rfc3339(as_str(input)).expect("RFC 3339 datetime")
}

fn parse_naive(input: &[u8]) -> NaiveDateTime {
    let text = as_str(input);
    NaiveDateTime::parse_from_str(text, "%Y-%m-%dT%H:%M:%S%.f")
        .or_else(|_| NaiveDateTime::parse_from_str(text, "%Y-%m-%dT%H:%M:%S"))
        .expect("naive datetime")
}

fn parse_date(input: &[u8]) -> NaiveDate {
    NaiveDate::parse_from_str(as_str(input), "%Y-%m-%d").expect("date")
}

fn parse_time(input: &[u8]) -> NaiveTime {
    let text = as_str(input);
    NaiveTime::parse_from_str(text, "%H:%M:%S%.f")
        .or_else(|_| NaiveTime::parse_from_str(text, "%H:%M:%S"))
        .expect("time")
}

fn parse_timedelta(input: &[u8]) -> TimeDelta {
    let micros = as_str(input).parse::<i128>().expect("microseconds");
    let negative = micros < 0;
    let magnitude = micros.unsigned_abs();
    let seconds = (magnitude / 1_000_000) as i64;
    let nanos = ((magnitude % 1_000_000) * 1_000) as u32;
    let delta = if !negative {
        TimeDelta::new(seconds, nanos)
    } else if nanos == 0 {
        TimeDelta::new(-seconds, 0)
    } else {
        TimeDelta::new(-seconds - 1, 1_000_000_000 - nanos)
    };
    delta.expect("timedelta in range")
}

fn as_str(bytes: &[u8]) -> &str {
    std::str::from_utf8(bytes).expect("utf-8 input")
}

// ---------------------------------------------------------------------------
// Runner
// ---------------------------------------------------------------------------

#[derive(Default)]
struct Summary {
    cases: usize,
    renders: usize,
    mismatches: Vec<String>,
    counts: BTreeMap<String, usize>,
    dialects: BTreeMap<String, usize>,
}

fn golden_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden")
}

#[test]
fn golden_corpus() {
    let directory = golden_dir();
    let mut files: Vec<PathBuf> = fs::read_dir(&directory)
        .unwrap_or_else(|error| panic!("read {}: {error}", directory.display()))
        .map(|entry| entry.expect("directory entry").path())
        .filter(|path| {
            path.extension()
                .is_some_and(|extension| extension == "jsonl")
        })
        .collect();
    files.sort();
    assert!(
        !files.is_empty(),
        "no golden files in {}",
        directory.display()
    );

    let mut summary = Summary::default();
    for file in &files {
        run_file(file, &mut summary);
    }

    println!(
        "golden corpus: {} cases, {} renders (one per dialect), {} MiB",
        summary.cases,
        summary.renders,
        fs::metadata(&directory)
            .map(|_| files
                .iter()
                .filter_map(|path| fs::metadata(path).ok())
                .map(|meta| meta.len())
                .sum::<u64>())
            .unwrap_or(0) as f64
            / 1_048_576.0
    );
    println!("per category:");
    for (category, count) in &summary.counts {
        println!("  {category:24} {count:6}");
    }
    println!("per dialect:");
    for (dialect, count) in &summary.dialects {
        println!("  {dialect:24} {count:6}");
    }

    if !summary.mismatches.is_empty() {
        let shown = summary.mismatches.len().min(25);
        let mut message = String::new();
        writeln!(
            message,
            "{} mismatches (showing {shown}):",
            summary.mismatches.len()
        )
        .expect("write to string");
        for mismatch in &summary.mismatches[..shown] {
            writeln!(message, "{mismatch}").expect("write to string");
        }
        panic!("{message}");
    }
}

fn run_file(path: &Path, summary: &mut Summary) {
    let contents =
        fs::read_to_string(path).unwrap_or_else(|error| panic!("read {}: {error}", path.display()));
    for (line_number, line) in contents.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let record: Record = serde_json::from_str(line).unwrap_or_else(|error| {
            panic!(
                "{}:{}: bad record: {error}",
                path.display(),
                line_number + 1
            )
        });
        *summary.counts.entry(record.cat.clone()).or_default() += 1;
        summary.cases += 1;
        for dialect_name in &record.dialects {
            let dialect = Record::dialect(dialect_name);
            *summary.dialects.entry(dialect_name.clone()).or_default() += 1;
            summary.renders += 1;

            let result =
                std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| render(&record, dialect)))
                    .unwrap_or_else(|panic| {
                        panic!(
                            "{}:{}: panic rendering {} / {dialect_name}: {}",
                            path.display(),
                            line_number + 1,
                            record.cat,
                            panic_message(panic)
                        )
                    });

            match (result, record.error.unwrap_or(false)) {
                (Err(_), true) => {}
                (Ok(bytes), false) => {
                    let expected = decode_base64(record.out.as_deref().unwrap_or_default());
                    if bytes != expected {
                        summary.mismatches.push(format!(
                            "MISMATCH {}:{} cat={} dialect={}\n  input:    {}\n  expected: {}\n  got:      {}",
                            path.file_name().unwrap_or_default().to_string_lossy(),
                            line_number + 1,
                            record.cat,
                            dialect_name,
                            display_bytes(&decode_base64(&record.input)),
                            display_bytes(&expected),
                            display_bytes(&bytes),
                        ));
                    }
                }
                (Ok(bytes), true) => {
                    summary.mismatches.push(format!(
                        "MISMATCH {}:{} cat={} dialect={}: expected an error, got {}\n  input: {}",
                        path.file_name().unwrap_or_default().to_string_lossy(),
                        line_number + 1,
                        record.cat,
                        dialect_name,
                        display_bytes(&bytes),
                        display_bytes(&decode_base64(&record.input)),
                    ));
                }
                (Err(error), false) => {
                    summary.mismatches.push(format!(
                        "MISMATCH {}:{} cat={} dialect={}: unexpected error {error:?}\n  input: {}",
                        path.file_name().unwrap_or_default().to_string_lossy(),
                        line_number + 1,
                        record.cat,
                        dialect_name,
                        display_bytes(&decode_base64(&record.input)),
                    ));
                }
            }
        }
    }
}

fn panic_message(panic: Box<dyn std::any::Any + Send>) -> String {
    if let Some(message) = panic.downcast_ref::<&str>() {
        (*message).to_owned()
    } else if let Some(message) = panic.downcast_ref::<String>() {
        message.clone()
    } else {
        "<non-string panic>".to_owned()
    }
}

/// Printable form of an input or output, capped so a mismatch stays readable.
fn display_bytes(bytes: &[u8]) -> String {
    let capped = &bytes[..bytes.len().min(240)];
    match std::str::from_utf8(capped) {
        Ok(text) => format!(
            "{text:?}{}",
            if bytes.len() > capped.len() {
                "…"
            } else {
                ""
            }
        ),
        Err(_) => format!(
            "{:?}{}",
            capped,
            if bytes.len() > capped.len() {
                "…"
            } else {
                ""
            }
        ),
    }
}

// ---------------------------------------------------------------------------
// Base64 (standard alphabet, padding): avoids a dependency for the tests.
// ---------------------------------------------------------------------------

fn decode_base64(text: &str) -> Vec<u8> {
    fn value(byte: u8) -> Option<u8> {
        match byte {
            b'A'..=b'Z' => Some(byte - b'A'),
            b'a'..=b'z' => Some(byte - b'a' + 26),
            b'0'..=b'9' => Some(byte - b'0' + 52),
            b'+' => Some(62),
            b'/' => Some(63),
            _ => None,
        }
    }

    let bytes = text.as_bytes();
    let mut out = Vec::with_capacity(bytes.len() / 4 * 3);
    let mut accumulator: u32 = 0;
    let mut bits = 0;
    for &byte in bytes {
        if byte == b'=' {
            continue;
        }
        let value = value(byte).unwrap_or_else(|| panic!("invalid base64 byte {byte}"));
        accumulator = (accumulator << 6) | u32::from(value);
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((accumulator >> bits) as u8);
        }
    }
    out
}
